<div class="detail-grid"><label>Putaran review<input type="number" name="round" min="1" max="99" required value="{{ $row?->round ?? 1 }}"></label><label>Alias reviewer<input name="reviewer" maxlength="100" required value="{{ $row?->reviewer }}"></label></div><label>Komentar reviewer<textarea name="comment" maxlength="5000" required>{{ $row?->comment }}</textarea></label><label>Respons penulis<textarea name="response" maxlength="5000">{{ $row?->response }}</textarea></label><label>Lokasi revisi, misalnya Metode, halaman 4 paragraf 2<input name="location" maxlength="500" value="{{ $row?->location }}"></label><label>Status<select name="status"><option value="pending" @selected($row?->status!=='addressed')>Belum ditangani</option><option value="addressed" @selected($row?->status==='addressed')>Ditangani</option></select></label>
